import{_ as a,o as r,c as s,a5 as t}from"./chunks/framework.CslsFoWx.js";const i="/VendoraSystem-docs/captures/2026-11-09-role-a-chaud-seuil/10-ios-avant-ecran-cuisine.jpg",o="/VendoraSystem-docs/captures/2026-11-09-role-a-chaud-seuil/11-ios-apres-bascule-telephone-meme-processus.jpg",c="/VendoraSystem-docs/captures/2026-11-09-role-a-chaud-seuil/12-ios-lucas-connecte-telephone.jpg",n="/VendoraSystem-docs/captures/2026-11-09-role-a-chaud-seuil/13-ios-retour-ecran-cuisine-chef-lucas-avant-correctif.jpg",l="/VendoraSystem-docs/captures/2026-11-09-role-a-chaud-seuil/14-ios-barre-ecran-cuisine-corrigee.jpg",v=JSON.parse('{"title":"Rôle changé à chaud et seuil « en ligne » unique — captures sur la vraie stack (09/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-09-role-a-chaud-seuil.md","filePath":"generated/preuves/2026-11-09-role-a-chaud-seuil.md","lastUpdated":null}'),u={name:"preuves/2026-11-09-role-a-chaud-seuil.md"};function d(p,e,g,h,m,f){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="role-change-a-chaud-et-seuil-«-en-ligne-»-unique-—-captures-sur-la-vraie-stack-09-11-2026" tabindex="-1">Rôle changé à chaud et seuil « en ligne » unique — captures sur la vraie stack (09/11/2026) <a class="header-anchor" href="#role-change-a-chaud-et-seuil-«-en-ligne-»-unique-—-captures-sur-la-vraie-stack-09-11-2026" aria-label="Permalink to &quot;Rôle changé à chaud et seuil « en ligne » unique — captures sur la vraie stack (09/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-09-role-a-chaud-seuil</code> · 5 image(s) · 0 trace(s)</p><div><p>Carte Trello « Pilotage et appareils : changement de rôle à chaud, seuil en ligne unifié » (spec 01 RG-AUTH-31, spec 12 RG-RPT-35). Serveur Spring Boot du worktree (port 8101, base Postgres séparée), back-office Angular (<code>ng serve</code> 4311), simulateur iOS <strong>dédié</strong> (iPhone 16, iOS 26.2) appairé à ce serveur comme « Écran cuisine (démo) ». Commerce fictif « Le Petit Bistrot (démo) » (<code>help/tools/seed/seed-demo.py</code>) ; « Borne entrée (démo) » et « Téléphone de Lucas (démo) » appairés par l&#39;API, la borne vue il y a <strong>4 min</strong> (dernier contact réglé en base). Scénario web : <code>help/tools/web/scenarios/_docs-role-chaud-seuil.json</code> ; gestes iOS par le pilote XCUITest (<code>help/tools/mobile/pilote-ios/pi.py</code>).</p><h2 id="seuil-«-en-ligne-»-meme-etat-partout-back-office" tabindex="-1">Seuil « en ligne » : même état partout (back-office) <a class="header-anchor" href="#seuil-«-en-ligne-»-meme-etat-partout-back-office" aria-label="Permalink to &quot;Seuil « en ligne » : même état partout (back-office)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fichier</th><th>Ce qu&#39;on voit</th></tr></thead><tbody><tr><td><code>01-web-appareils-borne-4-min-en-ligne.webp</code></td><td>Page Appareils : la règle sous le titre (1, « moins de 3 min (5 min pour une borne) — même règle que les pages Bornes et En direct ») ; la <strong>borne vue il y a 4 min est « En ligne »</strong> (2) (avant : « Hors ligne », seuil de 3 min pour tous) ; l&#39;écran cuisine (le simulateur) en ligne (3) ; caisse et téléphone virtuels vus il y a 4 min : hors ligne (seuil 3 min).</td></tr><tr><td><code>02-web-bornes-meme-etat.webp</code></td><td>Page Bornes : la même borne « En ligne · vue il y a 4 min » (1), texte de la page « moins de 5 min, même règle que les pages Appareils et En direct ».</td></tr><tr><td><code>03-web-en-direct-meme-regle.webp</code></td><td>Tableau de bord « En direct » : tuile Appareils « en ligne (vus il y a moins de 3 min, bornes 5 min) » (1) ; Bornes 1 / 1 ; même liste d&#39;appareils hors ligne que la page Appareils.</td></tr></tbody></table><h2 id="changement-de-role-au-back-office-→-bascule-sans-redemarrage" tabindex="-1">Changement de rôle au back-office → bascule sans redémarrage <a class="header-anchor" href="#changement-de-role-au-back-office-→-bascule-sans-redemarrage" aria-label="Permalink to &quot;Changement de rôle au back-office → bascule sans redémarrage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fichier</th><th>Ce qu&#39;on voit</th></tr></thead><tbody><tr><td><code>04-web-confirmation-sans-relance.webp</code></td><td>Confirmation « Changer le rôle de « Écran cuisine (démo) » ? » : l&#39;appareil bascule tout seul à sa prochaine synchronisation, sans redémarrage — plus de « relancez l&#39;application ».</td></tr><tr><td><code>05-web-role-change-bascule-a-la-synchro.webp</code></td><td>Fiche après confirmation : « Rôle changé : Téléphone de salle. L&#39;appareil bascule tout seul à sa prochaine synchronisation, sans redémarrage » (1) ; la fiche montre déjà le profil de salle.</td></tr><tr><td><code>10-ios-avant-ecran-cuisine.jpg</code></td><td>iPhone avant : écran cuisine, poste Cuisine.</td></tr><tr><td><code>11-ios-apres-bascule-telephone-meme-processus.jpg</code></td><td>Moins de 15 s après la confirmation (rôle changé au back-office) : l&#39;iPhone affiche <strong>« Qui êtes-vous ? »</strong> du téléphone de salle. <strong>Même processus</strong> avant et après (<code>launchctl list</code> : PID 60177 inchangé ; première série : PID 58396 inchangé) — aucune relance, aucun ré-appairage.</td></tr><tr><td><code>12-ios-lucas-connecte-telephone.jpg</code></td><td>Lucas (serveur) se connecte avec son PIN : plan de salle.</td></tr><tr><td><code>13-ios-retour-ecran-cuisine-chef-lucas-avant-correctif.jpg</code></td><td>Rôle repassé en Écran cuisine depuis le back-office pendant que Lucas est connecté : ~25 s plus tard, écran cuisine avec <strong>« Chef : Lucas (salle) »</strong> présélectionné (sa session de téléphone est close, motif <code>DEVICE_ROLE_CHANGED</code>), même processus. Défaut visible : la barre de l&#39;écran cuisine écrasait le titre (« Cuisi… ») et l&#39;état de synchro sur huit lignes une fois le chef choisi, sur iPhone.</td></tr><tr><td><code>14-ios-barre-ecran-cuisine-corrigee.jpg</code></td><td>Correctif du lot : sur téléphone, les pastilles (chef, bons) passent sous le titre quand la barre ne tient pas sur une ligne (<code>ViewThatFits</code>).</td></tr></tbody></table><h2 id="android-a-capturer-par-l-integrateur-parite-du-code-et-des-tests" tabindex="-1">Android (à capturer par l&#39;intégrateur, parité du code et des tests) <a class="header-anchor" href="#android-a-capturer-par-l-integrateur-parite-du-code-et-des-tests" aria-label="Permalink to &quot;Android (à capturer par l&#39;intégrateur, parité du code et des tests)&quot;">​</a></h2><p>Pas d&#39;émulateur supplémentaire sur cette machine. Scène exacte à reproduire sur <code>emulator-5554</code> (téléphone) :</p><ol><li>Appairer l&#39;émulateur comme <strong>écran cuisine</strong> (« Écran cuisine (démo) ») au commerce de démo, choisir le poste « Cuisine » → capture « écran cuisine ».</li><li>Au back-office, <em>Réglages › Appareils</em> → fiche de l&#39;écran → <strong>Passer en Téléphone de salle</strong> → <strong>Changer de rôle</strong>.</li><li>Sans toucher l&#39;émulateur, attendre ≤ 30 s : <strong>« Qui êtes-vous ? »</strong> du téléphone de salle → capture ; <code>adb shell pidof pos.android</code> identique avant / après (pas de redémarrage).</li><li>Se connecter avec Lucas (PIN du fichier de secrets), puis au back-office repasser l&#39;appareil en <strong>Écran cuisine</strong> : ≤ 30 s plus tard l&#39;écran cuisine affiche « Chef : Lucas (salle) » → capture.</li></ol></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-09-role-a-chaud-seuil/10-ios-avant-ecran-cuisine.jpg" target="_blank"><img src="'+i+'" alt="10-ios-avant-ecran-cuisine.jpg" loading="lazy"></a><figcaption>10-ios-avant-ecran-cuisine.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-09-role-a-chaud-seuil/11-ios-apres-bascule-telephone-meme-processus.jpg" target="_blank"><img src="'+o+'" alt="11-ios-apres-bascule-telephone-meme-processus.jpg" loading="lazy"></a><figcaption>11-ios-apres-bascule-telephone-meme-processus.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-09-role-a-chaud-seuil/12-ios-lucas-connecte-telephone.jpg" target="_blank"><img src="'+c+'" alt="12-ios-lucas-connecte-telephone.jpg" loading="lazy"></a><figcaption>12-ios-lucas-connecte-telephone.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-09-role-a-chaud-seuil/13-ios-retour-ecran-cuisine-chef-lucas-avant-correctif.jpg" target="_blank"><img src="'+n+'" alt="13-ios-retour-ecran-cuisine-chef-lucas-avant-correctif.jpg" loading="lazy"></a><figcaption>13-ios-retour-ecran-cuisine-chef-lucas-avant-correctif.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-09-role-a-chaud-seuil/14-ios-barre-ecran-cuisine-corrigee.jpg" target="_blank"><img src="'+l+'" alt="14-ios-barre-ecran-cuisine-corrigee.jpg" loading="lazy"></a><figcaption>14-ios-barre-ecran-cuisine-corrigee.jpg</figcaption></figure></div>',5)])])}const _=a(u,[["render",d]]);export{v as __pageData,_ as default};
